package app.veyra;
import android.app.*;import android.os.Bundle;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public final class CollectionsActivity extends Activity {
 private LinearLayout root;private String selected="";
 public void onCreate(Bundle saved){super.onCreate(saved);Ui.configure(this);if(saved!=null)selected=saved.getString("selected","");render();}
 private void render(){root=Ui.column(this);Button back=Ui.quiet(this,"‹  Back");back.setOnClickListener(v->{if(selected.isEmpty())finish();else{selected="";render();}});root.addView(back);root.addView(Ui.text(this,selected.isEmpty()?"Your collections":PersonalStore.collections(this).containsKey(selected)?PersonalStore.collections(this).get(selected).optString("name"):"Collection",30,Ui.INK));if(selected.isEmpty()){root.addView(Ui.text(this,ProfileStore.name(this)+" · lists for every mood",14,Ui.MUTED));for(Map.Entry<String,JSONObject> group:PersonalStore.collections(this).entrySet()){Button open=Ui.quiet(this,group.getValue().optString("name")+" · "+group.getValue().optJSONArray("titles").length()+" titles  ›");open.setSingleLine(false);open.setOnClickListener(v->{selected=group.getKey();render();});root.addView(open);}Button add=Ui.primary(this,"Create collection");add.setOnClickListener(v->{EditText name=new EditText(this);name.setHint("Collection name");name.setSingleLine(true);new AlertDialog.Builder(this).setTitle("New collection").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{try{PersonalStore.create(this,name.getText().toString());render();}catch(Exception e){Toast.makeText(this,"Use 1–40 characters; up to 20 collections",Toast.LENGTH_LONG).show();}}).show();});root.addView(add);}else{JSONObject group=PersonalStore.collections(this).get(selected);JSONArray titles=group==null?new JSONArray():group.optJSONArray("titles");for(int n=0;n<titles.length();n++){final int index=n;JSONObject title=titles.optJSONObject(n);LinearLayout row=Ui.card(this);Button open=Ui.quiet(this,title.optString("vod_name"));open.setSingleLine(false);open.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class).putExtra("openTitle",title.toString())));row.addView(open);Button remove=Ui.quiet(this,"Remove from collection");remove.setOnClickListener(v->{try{PersonalStore.remove(this,selected,index);render();}catch(Exception ignored){}});row.addView(remove);root.addView(row);}}ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);Ui.insets(this,scroll,20);}
 protected void onSaveInstanceState(Bundle state){state.putString("selected",selected);super.onSaveInstanceState(state);}
 public void onBackPressed(){if(selected.isEmpty())super.onBackPressed();else{selected="";render();}}
}
